import type { ReadonlyDb } from "@research-ts/db/client";
import type { Player } from "@research-ts/domain/player";
import { BOARD_MEMO_GROUP, createTtlMemo } from "@research-ts/lib/cache/ttl-memo";
import { nflPlayerIdsFor } from "../crosswalk";
import type { BoardReason } from "./board";
import { boardReasons } from "./board-store";

/**
 * How long a warm instance serves the board's reasons before re-reading them (Neon cost audit
 * 2026-09-07, finding 6). Both inputs are nightly writes — the board is regenerated by the
 * capsule sweep at 04:00 ET and the crosswalk by a one-shot build — so an hour can only ever lag
 * a write by a fraction of the write's own cadence.
 */
export const BOARD_REASONS_MEMO_TTL_MS = 60 * 60_000;

const memo = createTtlMemo<Readonly<Record<string, readonly BoardReason[]>>>(BOARD_REASONS_MEMO_TTL_MS, undefined, { group: BOARD_MEMO_GROUP });

/**
 * The pool's own law-backed reasons, keyed by the LEAGUE's own player id — `boardReasons` keys
 * by `nfl_players.id` (a gsis id), and the draft room only ever knows a `players.id`, so this is
 * the one place the two id spaces meet for this surface. A player the crosswalk could not place,
 * or one the board never ranked, is simply absent from the result — the same "absence means
 * nothing to say" rule `boardReasons` itself keeps, carried through one more join.
 *
 * Memoized per (source, season), NOT per league: the map is keyed by player id, and every
 * league's pool is the same player universe in a different order, so one read serves them all.
 * The 628 KB reasons read and the crosswalk read were the draft board's second-heaviest cost.
 */
export function reasonsByLeaguePlayerId(
  db: ReadonlyDb,
  players: readonly Player[],
  source: string,
  season: number,
): Promise<Readonly<Record<string, readonly BoardReason[]>>> {
  return memo.get(`${source}:${season}`, () => readReasonsByLeaguePlayerId(db, players, source, season));
}

async function readReasonsByLeaguePlayerId(
  db: ReadonlyDb,
  players: readonly Player[],
  source: string,
  season: number,
): Promise<Readonly<Record<string, readonly BoardReason[]>>> {
  const [crosswalk, byNflPlayerId] = await Promise.all([
    nflPlayerIdsFor(db, players.map((player) => player.id)),
    boardReasons(db, source, season),
  ]);
  const out: Record<string, readonly BoardReason[]> = {};
  for (const player of players) {
    const nflPlayerId = crosswalk.get(player.id);
    if (nflPlayerId === undefined) continue;
    const reasons = byNflPlayerId.get(nflPlayerId);
    if (reasons !== undefined) out[player.id] = reasons;
  }
  return out;
}
